def guide_markdown() -> str:
    """Le guide au format Markdown, généré depuis SECTIONS (jamais écrit à la main : on corrige ici, puis on régénère)."""
    out = ["# Gestion libre : guide d'utilisation", "",
           "> Ce fichier est GÉNÉRÉ depuis `gestion/aide.py` (la page « Aide » de l'application affiche le même texte). Pour le corriger : modifier `aide.py`, puis lancer `python outils/generer_guide.py`.", "",
           "**Sommaire** : " + " · ".join(f"[{i}. {s['title']}](#{s['id']})" for i, s in enumerate(SECTIONS, 1)), ""]
    for i, s in enumerate(SECTIONS, 1):
        out += [f'<a id="{s["id"]}"></a>', f"## {i}. {s['title']}", "", s["intro"], ""]
        out += [f"- {x}" for x in s["items"]]
        if s.get("note"): out += ["", f"**À retenir** : {s['note']}"]
        out.append("")
    return "\n".join(out).rstrip() + "\n"
